//! Typed consumer for `suikoden-menu-lists/1`.
//!
//! The packet is generated by the extraction pipeline from static disc
//! bytes and the existing port assets.  Nothing here executes original code or
//! invents a row: a forged count, label, source digest or anchor is refused by
//! `load`, and the menu model only receives rows the packet or the caller's
//! validated runtime state admits.

const std = @import("std");

pub const schema = "suikoden-menu-lists/1";
pub const base_snapshot = "6777466c31bce45577c18a3e4e960926875ed4a3";
pub const max_id = 40;
pub const max_label = 96;
pub const source_item_records: u16 = 179;
pub const admitted_items: u16 = 179;
pub const roster_capacity: u16 = 78;
pub const party_capacity: u16 = 6;
pub const bag_capacity: u16 = 9;
pub const storage_per_item: u16 = 254;
pub const save_slots: u16 = 3;

pub const Role = enum { command, separator };

pub const Row = struct {
    index: u16,
    id: ?[]const u8 = null,
    label: []const u8,
    role: Role = .command,
    ptr: ?[]const u8 = null,
    action: ?[]const u8 = null,
    handler: ?[]const u8 = null,
    arm: ?[]const u8 = null,
};

pub const List = struct {
    key: []const u8,
    kind: []const u8 = "source",
    screen: []const u8 = "",
    array: []const u8 = "",
    row_count: u16 = 0,
    rows: []const Row,
    wrap: bool = true,
    wrap_evidence: []const u8 = "",
    note: []const u8 = "",
    evidence: []const u8 = "",
};

pub const Descriptor = struct {
    index: u16,
    kind: i16,
    x: i16,
    y: i16,
    w: i16,
    rows: i16,
};

pub const WindowInfo = struct {
    text_width: u16,
    visible_rows: u16,
    descriptor_index: u16,
    derivation: []const u8,
};

pub const Window = struct {
    key: []const u8,
    table: []const u8,
    count: u16,
    rows: []const Descriptor,
    window: WindowInfo,
};

pub const RuntimeList = struct {
    key: []const u8,
    identity: []const u8,
    capacity: u16,
    label: []const u8,
    active_capacity: u16 = 0,
    per_item_quantity: u16 = 0,
    evidence: []const u8 = "",
};

pub const Character = struct {
    id: []const u8,
    name: []const u8,
    source_character_id: u16,
    record: u16,
    record_addr: []const u8,
};

pub const Item = struct {
    id: []const u8,
    label: []const u8,
    uses: u16,
    kind: []const u8,
    source_records: []const u16,
    ambiguous: bool = false,
};

pub const LongEntry = struct { id: ?[]const u8 = null, label: []const u8, cells: u16, list: ?[]const u8 = null };

pub const LongLabels = struct {
    item: []const LongEntry,
    roster: []const LongEntry,
    service: []const LongEntry,
    max_item_cells: u16,
    max_roster_cells: u16,
    max_label: u16,
};

pub const Anchor = struct {
    addr: []const u8,
    word: []const u8,
    note: []const u8,
    overlay: ?[]const u8 = null,
};

pub const Blocked = struct { id: []const u8, count: u16, detail: []const u8 };

pub const FileRef = struct {
    file: []const u8 = "",
    path: []const u8 = "",
    sha256: []const u8 = "",
    lba: u32 = 0,
    size: u32 = 0,
    image_base: []const u8 = "",
    base: []const u8 = "",
};

pub const Source = struct {
    main_exe: FileRef,
    slus: FileRef,
    warehouse_overlay: FileRef,
    party_catalogue: FileRef,
    items_source: FileRef,
    items_json: FileRef,
    menu_flow_tool: FileRef,
};

pub const Capacities = struct {
    party: u16,
    roster: u16,
    bag: u16,
    storage_per_item: u16,
    save_slots: u16,
    admitted_items: u16,
    source_item_records: u16,
    source_portraits: u16,
};

pub const Packet = struct {
    schema: []const u8,
    target: []const u8,
    base_snapshot: []const u8,
    producer: []const u8,
    source: Source,
    capacities: Capacities,
    windows: []const Window,
    lists: []const List,
    port_lists: []const List,
    runtime_lists: []const RuntimeList,
    roster: []const Character,
    items: []const Item,
    long_labels: LongLabels,
    anchors: []const Anchor,
    blocked: []const Blocked,
};

pub const Opened = struct {
    parsed: std.json.Parsed(Packet),

    pub fn deinit(self: *Opened) void {
        self.parsed.deinit();
    }

    pub fn packet(self: *const Opened) *const Packet {
        return &self.parsed.value;
    }

    pub fn list(self: *const Opened, key: []const u8) ?*const List {
        const value = &self.parsed.value;
        for (value.lists) |*candidate| if (std.mem.eql(u8, candidate.key, key)) return candidate;
        for (value.port_lists) |*candidate| if (std.mem.eql(u8, candidate.key, key)) return candidate;
        return null;
    }

    pub fn character(self: *const Opened, id: []const u8) ?*const Character {
        for (self.parsed.value.roster) |*candidate| if (std.mem.eql(u8, candidate.id, id)) return candidate;
        return null;
    }

    pub fn item(self: *const Opened, id: []const u8) ?*const Item {
        for (self.parsed.value.items) |*candidate| if (std.mem.eql(u8, candidate.id, id)) return candidate;
        return null;
    }

    pub fn window(self: *const Opened, key: []const u8) ?*const Window {
        for (self.parsed.value.windows) |*candidate| if (std.mem.eql(u8, candidate.key, key)) return candidate;
        return null;
    }
};

pub const Error = error{
    InvalidPacket,
    InvalidSchema,
    InvalidBaseSnapshot,
    InvalidSourceDigest,
    InvalidCount,
    InvalidRoster,
    InvalidItem,
    InvalidList,
    InvalidWindow,
    InvalidAnchor,
    InvalidLongLabels,
    DuplicateId,
};

fn nonEmpty(value: []const u8) bool {
    return value.len > 0;
}

fn digestOk(value: []const u8) bool {
    if (value.len != 64) return false;
    for (value) |byte| if (!std.ascii.isHex(byte)) return false;
    return true;
}

fn uniqueKeys(lists: []const List) bool {
    for (lists, 0..) |list, index| {
        if (!nonEmpty(list.key)) return false;
        for (lists[0..index]) |prior| if (std.mem.eql(u8, prior.key, list.key)) return false;
    }
    return true;
}

fn checkRows(list: List) Error!void {
    if (list.rows.len != list.row_count and !std.mem.eql(u8, list.kind, "port")) return error.InvalidList;
    if (list.rows.len == 0 or list.rows.len > 32) return error.InvalidCount;
    for (list.rows, 0..) |row, index| {
        if (row.index != index) return error.InvalidList;
        if (row.label.len > max_label) return error.InvalidLongLabels;
        if (row.role == .separator and row.label.len != 0) return error.InvalidList;
        if (row.role == .command and row.label.len == 0) return error.InvalidList;
        for (list.rows[0..index]) |prior| {
            if (row.role == .command and prior.role == .command and std.mem.eql(u8, prior.label, row.label)) return error.InvalidList;
        }
    }
}

fn checkWindow(window: Window) Error!void {
    if (!nonEmpty(window.key) or !nonEmpty(window.table)) return error.InvalidWindow;
    if (window.count != window.rows.len or window.rows.len == 0 or window.rows.len > 32) return error.InvalidCount;
    if (window.window.visible_rows == 0 or window.window.visible_rows > 32) return error.InvalidWindow;
    if (window.window.descriptor_index >= window.rows.len) return error.InvalidWindow;
    const chosen = window.rows[window.window.descriptor_index];
    if (chosen.w != window.window.text_width or chosen.rows != window.window.visible_rows) return error.InvalidWindow;
    for (window.rows, 0..) |row, index| {
        if (row.index != index) return error.InvalidWindow;
        if (row.rows <= 0 or row.w <= 0) return error.InvalidWindow;
    }
}

pub fn load(allocator: std.mem.Allocator, bytes: []const u8) !Opened {
    if (bytes.len > 4 * 1024 * 1024) return error.InvalidPacket;
    var parsed = try std.json.parseFromSlice(Packet, allocator, bytes, .{
        .allocate = .alloc_always,
        .ignore_unknown_fields = false,
    });
    errdefer parsed.deinit();
    const value = &parsed.value;
    if (!std.mem.eql(u8, value.schema, schema)) return error.InvalidSchema;
    if (!std.mem.eql(u8, value.base_snapshot, base_snapshot)) return error.InvalidBaseSnapshot;
    if (!std.mem.eql(u8, value.target, "Suikoden US v1.1 SLUS_002.92")) return error.InvalidPacket;
    if (!nonEmpty(value.producer)) return error.InvalidPacket;
    for ([_]*const FileRef{
        &value.source.main_exe,
        &value.source.slus,
        &value.source.warehouse_overlay,
        &value.source.party_catalogue,
        &value.source.items_source,
        &value.source.items_json,
        &value.source.menu_flow_tool,
    }) |file| {
        if (!digestOk(file.sha256)) return error.InvalidSourceDigest;
    }
    if (value.capacities.party != party_capacity or
        value.capacities.roster != roster_capacity or
        value.capacities.bag != bag_capacity or
        value.capacities.storage_per_item != storage_per_item or
        value.capacities.save_slots != save_slots or
        value.capacities.admitted_items != admitted_items or
        value.capacities.source_item_records != source_item_records or
        value.capacities.source_portraits != 108) return error.InvalidCount;

    if (!uniqueKeys(value.lists) or !uniqueKeys(value.port_lists)) return error.InvalidList;
    for (value.lists) |list| {
        if (!std.mem.eql(u8, list.kind, "source")) return error.InvalidList;
        if (!nonEmpty(list.screen) or !nonEmpty(list.array) or !nonEmpty(list.evidence)) return error.InvalidList;
        try checkRows(list);
    }
    for (value.port_lists) |list| {
        if (!std.mem.eql(u8, list.kind, "port")) return error.InvalidList;
        if (list.rows.len == 0 or list.rows.len > 32) return error.InvalidCount;
        for (list.rows, 0..) |row, index| {
            if (row.index != index or !nonEmpty(row.label) or row.label.len > max_label) return error.InvalidList;
        }
    }
    if (value.lists.len != 11) return error.InvalidCount;
    if (value.windows.len != 6) return error.InvalidCount;
    var descriptor_count: u16 = 0;
    for (value.windows, 0..) |window, index| {
        try checkWindow(window);
        descriptor_count += window.count;
        for (value.windows[0..index]) |prior| if (std.mem.eql(u8, prior.key, window.key)) return error.InvalidWindow;
    }
    if (descriptor_count != 57) return error.InvalidCount;

    if (value.roster.len != roster_capacity) return error.InvalidRoster;
    for (value.roster, 0..) |character, index| {
        if (!nonEmpty(character.id) or character.id.len > max_id) return error.InvalidRoster;
        if (!nonEmpty(character.name) or character.name.len > max_label) return error.InvalidRoster;
        if (character.source_character_id > 109 or character.record != index) return error.InvalidRoster;
        for (value.roster[0..index]) |prior| {
            if (std.mem.eql(u8, prior.id, character.id)) return error.DuplicateId;
            if (prior.source_character_id == character.source_character_id) return error.DuplicateId;
        }
    }
    if (value.items.len != admitted_items) return error.InvalidItem;
    for (value.items, 0..) |item, index| {
        if (!nonEmpty(item.id) or item.id.len > max_id) return error.InvalidItem;
        if (!nonEmpty(item.label) or item.label.len > max_label) return error.InvalidItem;
        if (item.source_records.len == 0) return error.InvalidItem;
        for (item.source_records) |record| {
            if (record == 0 or record > source_item_records) return error.InvalidItem;
        }
        for (value.items[0..index]) |prior| if (std.mem.eql(u8, prior.id, item.id)) return error.DuplicateId;
    }
    if (value.long_labels.item.len == 0 or value.long_labels.roster.len == 0 or
        value.long_labels.service.len == 0) return error.InvalidLongLabels;
    if (value.long_labels.max_item_cells != 20 or value.long_labels.max_roster_cells != 8) return error.InvalidLongLabels;
    for (value.long_labels.item) |entry| {
        if (entry.cells != entry.label.len or entry.cells > value.long_labels.max_item_cells) return error.InvalidLongLabels;
    }
    for (value.long_labels.roster) |entry| {
        if (entry.cells != entry.label.len or entry.cells > value.long_labels.max_roster_cells) return error.InvalidLongLabels;
    }
    if (value.anchors.len < 24) return error.InvalidAnchor;
    for (value.anchors) |anchor| {
        if (!nonEmpty(anchor.addr) or !nonEmpty(anchor.word) or !nonEmpty(anchor.note)) return error.InvalidAnchor;
    }
    if (value.blocked.len == 0) return error.InvalidPacket;
    if (value.runtime_lists.len < 6) return error.InvalidCount;
    for (value.runtime_lists) |runtime| {
        if (!nonEmpty(runtime.key) or runtime.capacity == 0 or runtime.capacity > 254) return error.InvalidCount;
    }
    return .{ .parsed = parsed };
}
